package com.collab.badges.consumer;

import com.collab.badges.entity.UserBadgeCounter;
import com.collab.badges.event.BadgeIncrementMessage;
import com.collab.badges.repository.BadgeCounterRepository;
import com.collab.badges.service.WorkspaceMembershipService;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.messaging.handler.annotation.Payload;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Component;

@Component
public class NotificationBadgeConsumer {

    private final BadgeCounterRepository counterRepository;
    private final WorkspaceMembershipService membershipService;

    public NotificationBadgeConsumer(BadgeCounterRepository counterRepository, WorkspaceMembershipService membershipService) {
        this.counterRepository = counterRepository;
        this.membershipService = membershipService;
    }

    @KafkaListener(topics = "user-badge-counters", groupId = "notification-counter-service")
    public void incrementBadgeCounter(@Payload BadgeIncrementMessage message) {
        if (!membershipService.isUserMemberOfWorkspace(message.getTargetUserId(), message.getTriggerWorkspaceId())) {
            throw new AccessDeniedException("Cannot dispatch notification badge increments across unshared workspaces");
        }
        UserBadgeCounter counter = counterRepository.findByUserIdAndCategory(message.getTargetUserId(), message.getBadgeCategory())
                .orElseGet(() -> new UserBadgeCounter(message.getTargetUserId(), message.getBadgeCategory(), 0));
        counter.setCount(counter.getCount() + message.getIncrementDelta());
        counterRepository.save(counter);
    }
}
